files.content:
:root {
  --bg: #f4f1ea;
  --card: #ffffff;
  --primary: #4a6fa5;
  --primary-dark: #3a5a8a;
  --accent: #e07a5f;
  --text: #2d2d2d;
  --muted: #6b6b6b;
  --border: #d0ccc5;
  --radius: 12px;
  --shadow: 0 4px 12px rgba(0,0,0,0.08);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

.journal {
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 28px 24px;
  width: 100%;
  max-width: 520px;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 20px;
  text-align: center;
  color: var(--primary);
  letter-spacing: -0.5px;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0 0 20px;
}

legend {
  font-weight: 600;
  margin-bottom: 12px;
  font-size: 1rem;
}

.mood-options {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.mood-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  padding: 8px 10px;
  border-radius: 8px;
  border: 2px solid transparent;
  transition: border-color 0.15s, background 0.15s;
  min-width: 60px;
}

.mood-label:hover {
  background: #f0ede8;
}

.mood-label:focus-within {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.mood-label:has(input:checked) {
  border-color: var(--primary);
  background: #e8eef7;
}

.mood-label:active {
  background: #dde5f0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.mood-face {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  position: relative;
  image-rendering: pixelated;
  box-shadow: inset 0 0 0 2px rgba(0,0,0,0.1);
}

.mood-face::before,
.mood-face::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  background: #2d2d2d;
  border-radius: 2px;
}

.mood-face::before { top: 14px; left: 12px; }
.mood-face::after  { top: 14px; right: 12px; }

.happy { background: #f2cc8f; }
.happy .mouth,
.happy::after { }

.mood-face.happy { background: #f2cc8f; }
.mood-face.happy::before,
.mood-face.happy::after { background: #2d2d2d; }

.mood-face.happy {
  background-image: radial-gradient(circle at 24px 30px, #2d2d2d 0 2px, transparent 2px),
                    radial-gradient(circle at 24px 34px, #2d2d2d 0 2px, transparent 2px);
}

.mood-face.sad { background: #a8c6e8; }
.mood-face.sad::before,
.mood-face.sad::after { background: #2d2d2d; }
.mood-face.sad { background-image: radial-gradient(circle at 24px 34px, #2d2d2d 0 2px, transparent 2px); }

.mood-face.angry { background: #e07a5f; }
.mood-face.angry::before,
.mood-face.angry::after { background: #2d2d2d; }
.mood-face.angry { background-image: linear-gradient(45deg, transparent 40%, #2d2d2d 40%, #2d2d2d 60%, transparent 60%); }

.mood-face.tired { background: #b8b8b8; }
.mood-face.tired::before,
.mood-face.tired::after { background: #2d2d2d; }
.mood-face.tired { background-image: linear-gradient(to bottom, transparent 45%, #2d2d2d 45%, #2d2d2d 55%, transparent 55%); }

.mood-face.excited { background: #f2cc8f; }
.mood-face.excited::before,
.mood-face.excited::after { background: #2d2d2d; }
.mood-face.excited { background-image: radial-gradient(circle at 24px 30px, #2d2d2d 0 2px, transparent 2px),
                    radial-gradient(circle at 24px 36px, #2d2d2d 0 2px, transparent 2px); }

.mood-name {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text);
}

.note-section {
  margin-bottom: 16px;
}

.note-section label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 0.95rem;
}

textarea {
  width: 100%;
  padding: 10px 12px;
  border: 2px solid var(--border);
  border-radius: 8px;
  font-family: inherit;
  font-size: 1rem;
  resize: vertical;
  background: #faf9f7;
  transition: border-color 0.15s;
}

textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(74,111,165,0.2);
}

.btn-primary {
  display: block;
  width: 100%;
  padding: 12px;
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-bottom: 24px;
}

.btn-primary:hover {
  background: var(--primary-dark);
}

.btn-primary:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn-primary:active {
  transform: scale(0.98);
}

.entries-section h2 {
  font-size: 1.2rem;
  margin: 0 0 12px;
  color: var(--primary);
}

.mood-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
  font-size: 0.85rem;
}

.mood-count {
  background: #f0ede8;
  padding: 4px 10px;
  border-radius: 20px;
  color: var(--muted);
  font-weight: 500;
}

.entries-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.entry {
  background: #faf9f7;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.entry-face {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 2px;
}

.entry-face.happy { background: #f2cc8f; }
.entry-face.sad { background: #a8c6e8; }
.entry-face.angry { background: #e07a5f; }
.entry-face.tired { background: #b8b8b8; }
.entry-face.excited { background: #f2cc8f; }

.entry-content {
  flex: 1;
  min-width: 0;
}

.entry-date {
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 2px;
}

.entry-note {
  font-size: 0.95rem;
  word-break: break-word;
}

.entry-empty {
  text-align: center;
  color: var(--muted);
  font-size: 0.9rem;
  padding: 20px 0;
}

@media (max-width: 400px) {
  .journal { padding: 20px 16px; }
  h1 { font-size: 1.4rem; }
  .mood-face { width: 40px; height: 40px; }
  .mood-face::before, .mood-face::after { width: 7px; height: 7px; }
  .mood-name { font-size: 0.75rem; }
}

(function() {
  'use strict';

  var entries = [];
  var STORAGE_KEY = 'pixelMoodJournalEntries';

  function loadEntries() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) entries = JSON.parse(raw);
    } catch (e) { entries = []; }
  }

  function saveEntries() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(entries)); } catch (e) {}
  }

  function formatDate(iso) {
    var d = new Date(iso);
    return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  }

  function renderCounts() {
    var counts = {};
    entries.forEach(function(e) { counts[e.mood] = (counts[e.mood] || 0) + 1; });
    var moods = ['happy','sad','angry','tired','excited'];
    var container = document.getElementById('mood-counts');
    container.innerHTML = moods.map(function(m) {
      return '<span class="mood-count">' + m.charAt(0).toUpperCase() + m.slice(1) + ': ' + (counts[m] || 0) + '</span>';
    }).join('');
  }

  function renderEntries() {
    var list = document.getElementById('entries-list');
    if (entries.length === 0) {
      list.innerHTML = '<li class="entry-empty">No entries yet. Add your first mood!</li>';
      return;
    }
    var sorted = entries.slice().sort(function(a, b) { return new Date(b.date) - new Date(a.date); });
    list.innerHTML = sorted.map(function(e) {
      return '<li class="entry">' +
        '<span class="entry-face ' + e.mood + '" aria-hidden="true"></span>' +
        '<div class="entry-content">' +
          '<div class="entry-date">' + formatDate(e.date) + ' — ' + e.mood.charAt(0).toUpperCase() + e.mood.slice(1) + '</div>' +
          (e.note ? '<div class="entry-note">' + escapeHtml(e.note) + '</div>' : '') +
        '</div>' +
      '</li>';
    }).join('');
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  function render() {
    renderCounts();
    renderEntries();
  }

  function addEntry() {
    var selected = document.querySelector('input[name="mood"]:checked');
    if (!selected) return;
    var note = document.getElementById('note').value.trim();
    entries.push({
      mood: selected.value,
      note: note,
      date: new Date().toISOString()
    });
    saveEntries();
    document.getElementById('note').value = '';
    render();
  }

  function init() {
    loadEntries();
    render();
    document.getElementById('add-entry').addEventListener('click', addEntry);
    document.getElementById('note').addEventListener('keydown', function(e) {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        addEntry();
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
